import {sceneName,filterLines,tokenize,labels,advanceProgress,plain} from './data.js';
import {icon,esc,el,button,openSheet,isSheetOpen,toast,closeSheet} from './ui.js';
export function directionText(d){return typeof d==='string'?d:plain(d?.ja);}
export function showDirection(line){const d=line.direction;openSheet('ト書き',`<p>${esc(directionText(d)||'日本語要約は未収録です。')}</p>${typeof d==='object'&&d.original?`<div class="sheet-section"><h3>原文</h3><p lang="en">${esc(d.original)}</p><p class="subtle">出典: ${esc(d.source||'読み込みデータ')}</p></div>`:''}`);}
export function showDictionary(line,token,ctx){const entries=ctx.data.dictionary,key=String(token.entry?.lemma||token.text).toLowerCase(),d=entries[key]||Object.values(entries).find(v=>v.lemma?.toLowerCase()===key),v=token.entry;
 openSheet(v?.lemma||d?.lemma||token.text,`<div class="dictionary-word" lang="en">${esc(v?.lemma||d?.lemma||token.text)}</div><div class="dictionary-meta">${esc(d?.pos||'品詞未収録')} ${esc(d?.ipa||'')}</div>${d||v?`<p class="meaning">${esc(d?.coreMeaning||v.meaning)}</p><div class="sheet-section"><h3>このセリフでは</h3><p>${esc(v?.meaning||d.contextMeaning||'個別の語釈は未収録です。')}</p>${d?.contextExplanation?`<p class="subtle" style="margin-top:10px">${esc(d.contextExplanation)}</p>`:''}</div>${d?.pattern||d?.forms?`<div class="sheet-section"><h3>語法・表現</h3>${d.pattern?`<p lang="en"><strong>${esc(d.pattern)}</strong></p>`:''}<p>${esc(d.patternDesc||d.forms)}</p></div>`:''}`:`<p>この単語の辞書データは未収録です。</p><p class="subtle" style="margin-top:12px">発話の解析から、日本語訳と登録済みの表現を確認できます。</p>`}<div class="sheet-section"><h3>セリフ</h3><p lang="en" class="analysis-quote">${esc(line.text)}</p>${button('文章解析を開く','analyze-word','secondary')}</div>`,{setup:sheet=>{sheet.querySelector('[data-action=analyze-word]').onclick=()=>showAnalysis(line,ctx);}});
}
export function showAnalysis(line,ctx){const {data,progress,small,setProgress,save}=ctx,t=data.translations[line.id],translation=typeof t==='string'?t:t?.translation,grammar=data.grammar[line.id]||[],vocab=data.vocabulary[line.id]||[],p=progress[line.id]||{},note=small.notes?.[line.id]||{};
 openSheet(`${line.speaker} · 発話 ${line.ordinal}`,`<p lang="en" class="analysis-quote">${esc(line.text)}</p><h3 class="eyebrow" style="margin-bottom:10px">日本語訳</h3><p>${esc(translation||'日本語訳は未収録です。')}</p><div class="sheet-section"><h3>学習状態</h3><div class="button-row">${button(labels[p.level||0],'level-analysis','secondary','check')}${button(p.review?'要復習を解除':'要復習に追加','review-analysis','secondary','bookmark')}</div></div><div class="sheet-section"><h3>文法・構文</h3>${grammar.length?grammar.map(g=>`<div class="grammar-item"><strong>${esc(g.pattern)}</strong><p>${esc(g.description)}</p></div>`).join(''):'<p class="subtle">この発話の文法解説は未収録です。</p>'}</div><div class="sheet-section"><h3>重要表現</h3>${vocab.length?vocab.map((v,i)=>`<button class="scene-link" data-vocab="${i}"><span class="scene-link-text"><strong lang="en">${esc(v.surface)}</strong><small>${esc(v.meaning)}</small></span>${icon('chevron')}</button>`).join(''):'<p class="subtle">登録された重要表現はありません。</p>'}</div><div class="sheet-section"><h3>文脈・発話意図</h3>${line.context?`<p>${esc(line.context)}</p>`:'<p class="subtle">解説は未収録です。前後のやり取りを確認し、自分の解釈を残せます。</p>'}<label class="form-stack" style="margin-top:12px;font-size:12px">自分の解釈<input id="context-note" placeholder="相手に何を伝えたい？" value="${esc(note.context||'')}" maxlength="2000"></label></div><div class="sheet-section"><h3>演技のポイント</h3>${line.acting?`<p>${esc(line.acting)}</p>`:'<p class="subtle">演技解説は未収録です。演出の指示や、自分の演技プランを記録できます。</p>'}<label class="form-stack" style="margin-top:12px;font-size:12px">演技メモ<input id="acting-note" placeholder="間の取り方・視線・強調する語など" value="${esc(note.acting||'')}" maxlength="2000"></label><p class="subtle" style="margin-top:10px;font-size:11px">メモは自動保存。原文のト書きとは別に扱います。</p></div>${line.direction?`<div class="sheet-section"><h3>ト書き</h3><p>${esc(directionText(line.direction)||'日本語要約は未収録です。')}</p><details><summary>原文と出典</summary><p lang="en">${esc(line.direction.original||'原文未収録')}</p><p class="subtle">${esc(line.direction.source||'読み込みデータ')}</p></details></div>`:''}`,{setup:sheet=>{
 const level=sheet.querySelector('[data-action=level-analysis]'),review=sheet.querySelector('[data-action=review-analysis]');
 level.onclick=()=>{setProgress(line.id,advanceProgress(progress[line.id]));level.querySelector('span').textContent=labels[progress[line.id].level];};review.onclick=()=>{setProgress(line.id,{...progress[line.id],review:!progress[line.id]?.review,updatedAt:Date.now()});review.querySelector('span').textContent=progress[line.id].review?'要復習を解除':'要復習に追加';};
 sheet.querySelectorAll('[data-vocab]').forEach(b=>b.onclick=()=>showDictionary(line,{text:vocab[b.dataset.vocab].surface,entry:vocab[b.dataset.vocab]},ctx));
 const storeNote=()=>{small.notes||={};small.notes[line.id]={context:sheet.querySelector('#context-note').value,acting:sheet.querySelector('#acting-note').value};save();};sheet.querySelector('#context-note').oninput=storeNote;sheet.querySelector('#acting-note').oninput=storeNote;
 }});
}
export function speechNode(line,ctx,{words=true}={}){const p=ctx.progress[line.id]||{};const node=el(`<article class="speech ${line.speaker===ctx.small.role?'mine':''}" id="line-${esc(line.id)}" data-id="${esc(line.id)}" aria-label="${esc(line.speaker)}、発話 ${line.ordinal}"><div class="swipe-hint"></div><div class="speech-inner"><div class="speech-head"><span class="speaker">${esc(line.speaker)}</span><span class="line-number">${line.ordinal.toString().padStart(3,'0')}</span><div class="speech-tools"><button data-action="level" data-level="${p.level||0}" aria-label="学習状態: ${labels[p.level||0]}。タップで更新">${icon('check')}</button><button data-action="review" class="${p.review?'is-review':''}" aria-label="${p.review?'要復習を解除':'要復習に追加'}" aria-pressed="${!!p.review}">${icon('bookmark')}</button><button data-action="analysis" aria-label="発話 ${line.ordinal} の文章解析">${icon('more')}</button></div></div>${line.direction?`<button class="direction" data-action="direction">${esc(directionText(line.direction)||'ト書きを確認')} ${icon('down')}</button>`:''}<p class="speech-text" lang="en">${esc(line.text)}</p></div></article>`);
 node.querySelector('[data-action=analysis]').onclick=()=>showAnalysis(line,ctx);node.querySelector('[data-action=direction]')?.addEventListener('click',()=>showDirection(line));node.querySelector('[data-action=level]').onclick=()=>ctx.setProgress(line.id,advanceProgress(ctx.progress[line.id]));node.querySelector('[data-action=review]').onclick=()=>ctx.setProgress(line.id,{...ctx.progress[line.id],review:!ctx.progress[line.id]?.review,updatedAt:Date.now()});
 let suppressed=false;
 node.addEventListener('click',e=>{if(suppressed){e.preventDefault();e.stopImmediatePropagation();}else if(!e.target.closest('button,a,input,select'))showAnalysis(line,ctx);},true);
 node.renderWords=()=>{if(node.dataset.tokenized||!words)return;node.dataset.tokenized='1';const paragraph=node.querySelector('.speech-text');paragraph.replaceChildren();for(const token of tokenize(line.text,ctx.data.vocabulary[line.id]||[])){if(token.word||token.entry){const b=document.createElement('button');b.className='word'+(token.entry?' phrase':'');b.textContent=token.text;b.setAttribute('aria-label',`${token.text} の意味`);b.onclick=()=>showDictionary(line,token,ctx);paragraph.append(b);}else paragraph.append(document.createTextNode(token.text));}};
 let gesture;
 node.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button:not(.word)'))return;gesture={x:e.clientX,y:e.clientY,id:e.pointerId,dx:0,locked:false};},{passive:true});
 node.addEventListener('pointermove',e=>{if(!gesture||e.pointerId!==gesture.id)return;const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;if(!gesture.locked){if(Math.abs(dy)>10&&Math.abs(dy)>Math.abs(dx)){gesture=null;return;}if(Math.abs(dx)>12&&Math.abs(dx)>Math.abs(dy)*1.5){gesture.locked=true;node.setPointerCapture(e.pointerId);}else return;}gesture.dx=dx;const hint=node.querySelector('.swipe-hint');hint.style.opacity=Math.min(1,Math.abs(dx)/70);hint.textContent=dx>0?`→ ${labels[((ctx.progress[line.id]?.level||0)+1)%3]}`:'要復習を切り替え ←';hint.classList.toggle('left',dx<0);node.querySelector('.speech-inner').style.transform=`translateX(${Math.max(-100,Math.min(100,dx*.65))}px)`;});
 const reset=()=>{node.querySelector('.swipe-hint').style.opacity=0;node.querySelector('.speech-inner').style.transform='';};
 node.addEventListener('pointerup',e=>{if(!gesture||gesture.id!==e.pointerId)return;const g=gesture;gesture=null;if(g.locked){suppressed=true;setTimeout(()=>suppressed=false,300);if(Math.abs(g.dx)>68){if(g.dx>0)ctx.setProgress(line.id,advanceProgress(ctx.progress[line.id]));else ctx.setProgress(line.id,{...ctx.progress[line.id],review:!ctx.progress[line.id]?.review,updatedAt:Date.now()});}}reset();});node.addEventListener('pointercancel',()=>{gesture=null;reset();});
 return node;
}
export function updateSpeech(node,p={}){const level=node.querySelector('[data-action=level]');if(!level)return;level.dataset.level=p.level||0;level.setAttribute('aria-label',`学習状態: ${labels[p.level||0]}。タップで更新`);const review=node.querySelector('[data-action=review]');review.classList.toggle('is-review',!!p.review);review.setAttribute('aria-pressed',!!p.review);review.setAttribute('aria-label',p.review?'要復習を解除':'要復習に追加');}
export function mountReader(main,ctx){const {data,small,save,progress}=ctx;let destroyStick=()=>{},observer,scrollFrame,saveTimer,disposed=false;const visible=new Set();let lines=[];
 const root=el(`<div class="reader-top"><div class="reader-heading"><h1>台本</h1><span class="reader-count"></span></div><div class="reader-tools"><button class="icon-button" data-action="search" aria-label="検索と絞り込み" aria-expanded="false">${icon('search')}</button><button class="icon-button" data-action="scene" aria-label="幕・場面へ移動">${icon('book')}</button><button class="icon-button" data-action="type" aria-label="文字サイズを調整">${icon('type')}</button></div></div>`);main.append(root);
 const filters=el(`<div class="reader-filter hide"><label class="search-field">発話を検索<input type="search" placeholder="英文・日本語訳・話者" value="${esc(small.query||'')}" aria-label="発話を検索"></label><label>話者<select id="speaker-filter"><option value="all">すべての話者</option>${ctx.roles().map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select></label><label>表示<select id="review-filter"><option value="all">すべて</option><option value="review">要復習のみ</option></select></label><button class="text-button" data-action="clear-filters">条件をクリア</button></div>`);main.append(filters);
 const scroller=el('<div class="page-scroll reader-scroll" tabindex="0" aria-label="台本本文"></div>'),body=el('<div class="script-body"></div>');scroller.append(body);main.append(scroller);body.style.setProperty('--font',small.font+'px');body.style.setProperty('--reader-leading',small.leading);
 filters.querySelector('#speaker-filter').value=small.speaker||'all';filters.querySelector('#review-filter').value=small.reviewOnly?'review':'all';
 const nodeById=new Map();
 function current(){let best=null,dist=Infinity;const top=scroller.getBoundingClientRect().top;for(const n of visible){const r=n.getBoundingClientRect();if(r.bottom<top+40)continue;const d=Math.abs(r.top-top-55);if(d<dist){best=n;dist=d;}}return best;}
 function remember(){const n=current();if(n){small.read={id:n.dataset.id,offset:n.getBoundingClientRect().top-scroller.getBoundingClientRect().top,scene:small.scene};save();}}
 function jump(id,highlight=true,offset=null){const n=nodeById.get(id);if(!n){toast('この表示範囲に対象のセリフがありません');return;}n.renderWords();n.scrollIntoView({block:offset===null?'center':'start',behavior:'instant'});if(offset!==null)scroller.scrollTop-=offset;requestAnimationFrame(()=>{if(disposed)return;if(offset===null)n.scrollIntoView({block:'center',behavior:'instant'});else scroller.scrollTop+=n.getBoundingClientRect().top-scroller.getBoundingClientRect().top-offset;if(highlight){n.classList.add('highlight');setTimeout(()=>n.classList.remove('highlight'),1600);}});}
 function jumpMine(direction){if(isSheetOpen())return;const currentNode=current(),index=lines.findIndex(l=>l.id===currentNode?.dataset.id),target=direction>0?lines.find((l,i)=>i>index&&l.speaker===small.role):lines.slice(0,Math.max(0,index)).reverse().find(l=>l.speaker===small.role);if(target)jump(target.id);else toast(direction>0?'次の自分のセリフはありません':'前の自分のセリフはありません');}
 async function draw(restore=false){observer?.disconnect();visible.clear();nodeById.clear();body.replaceChildren();lines=filterLines(data,{scene:small.scene,speaker:small.speaker||'all',query:small.query||'',reviewOnly:small.reviewOnly,progress});root.querySelector('.reader-count').textContent=`${lines.length} 発話`;
 if(!lines.length){body.innerHTML='<div class="empty"><h2>該当するセリフがありません</h2><p>場面や検索・絞り込み条件を変更してください。</p></div>';return;}
 observer=new IntersectionObserver(entries=>{for(const e of entries){if(e.isIntersecting){visible.add(e.target);e.target.renderWords();}else visible.delete(e.target);}},{root:scroller,rootMargin:'200px 0px'});
 let scene='';const frag=document.createDocumentFragment();for(const line of lines){if(line.scene!==scene){scene=line.scene;frag.append(el(`<div class="scene-divider"><h2>${esc(sceneName(scene))}</h2></div>`));}const n=speechNode(line,ctx);nodeById.set(line.id,n);frag.append(n);}body.append(frag);for(const n of nodeById.values())observer.observe(n);
 if(restore&&small.read.id&&nodeById.has(small.read.id))jump(small.read.id,false,small.read.offset??40);else scroller.scrollTop=0;
 }
 const change=()=>{small.query=filters.querySelector('input').value;small.speaker=filters.querySelector('#speaker-filter').value;small.reviewOnly=filters.querySelector('#review-filter').value==='review';save();draw();};let queryTimer;
 filters.querySelector('input').oninput=()=>{clearTimeout(queryTimer);queryTimer=setTimeout(change,160);};filters.querySelectorAll('select').forEach(s=>s.onchange=change);filters.querySelector('[data-action=clear-filters]').onclick=()=>{filters.querySelector('input').value='';filters.querySelector('#speaker-filter').value='all';filters.querySelector('#review-filter').value='all';change();};
 root.querySelector('[data-action=search]').onclick=e=>{filters.classList.toggle('hide');e.currentTarget.setAttribute('aria-expanded',!filters.classList.contains('hide'));if(!filters.classList.contains('hide'))filters.querySelector('input').focus();};
 root.querySelector('[data-action=scene]').onclick=()=>openSheet('幕・場面へ移動',`<button class="scene-link" data-scene="all"><strong>全幕を連続して読む</strong></button>${data.scenes.map(s=>`<button class="scene-link" data-scene="${esc(s.id)}"><span class="scene-link-text"><strong>${esc(s.title)}</strong><small>${s.lines.length} 発話</small></span>${icon('chevron')}</button>`).join('')}`,{setup:sheet=>sheet.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{remember();small.scene=b.dataset.scene;small.read={};save();closeSheet();draw();})});
 root.querySelector('[data-action=type]').onclick=()=>openSheet('読みやすさ',`<label class="form-stack">英文の文字サイズ<input type="range" min="16" max="32" value="${small.font}" id="reader-size"></label><p class="subtle" style="margin-top:16px">本文中の単語をタップすると辞書、話者名や余白・「…」で文章解析を開きます。</p>`,{setup:sheet=>{sheet.querySelector('input').oninput=e=>{small.font=+e.target.value;body.style.setProperty('--font',small.font+'px');save();};}});
 scroller.addEventListener('scroll',()=>{if(scrollFrame)return;scrollFrame=requestAnimationFrame(()=>{scrollFrame=0;clearTimeout(saveTimer);saveTimer=setTimeout(remember,180);});},{passive:true});
 const onProgress=e=>{const n=nodeById.get(e.detail);if(n)updateSpeech(n,progress[e.detail]);};window.addEventListener('progresschange',onProgress);
 draw(true);if(small.stick)import('./stick.js').then(({mountStick})=>{if(!disposed)destroyStick=mountStick(main.closest('.main-shell'),scroller,jumpMine);});
 const onHide=()=>{if(document.hidden)remember();};document.addEventListener('visibilitychange',onHide);window.addEventListener('pagehide',remember);
 return ()=>{remember();disposed=true;destroyStick();observer?.disconnect();clearTimeout(saveTimer);clearTimeout(queryTimer);cancelAnimationFrame(scrollFrame);window.removeEventListener('progresschange',onProgress);document.removeEventListener('visibilitychange',onHide);window.removeEventListener('pagehide',remember);};
}
